  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Create a new IPO application for a target company.
   * A retail customer can start an IPO application by providing a company, a share count greater than 0,
   * a payment amount greater than 0, and a non-null allowance document.
   * The customer must be eligible for IPO and must not already have an approved application for the same company.
   * Algorithm:
   * 1. Validate input:
   *    - company is not null
   *    - shares > 0
   *    - amount > 0
   *    - doc is not null
   * 2. Check isEligibleForIPO().
   * 3. Search existing applications for an approved application with the same company.name.
   * 4. If customer is not eligible or such approved application exists, return false.
   * 5. Create a new Application with:
   *    - company
   *    - customer = this
   *    - share = shares
   *    - amountOfMoney = amount
   *    - allowance = doc
   *    - status = PENDING
   * 6. Add the new Application to applications.
   * 7. Return true.
   * Related Features:
   * - applications
   * - canApplyForIPO
   * - createApplication(company, shares, amount, doc)
   * - isEligibleForIPO()
   * Related Classes: Application, Company, Document, ApplicationStatus
   * Input:
   * - company : Company
   *   - Target company for the IPO application.
   * - shares : int
   *   - Number of shares requested.
   *   - Must be greater than 0.
   * - amount : double
   *   - Payment amount.
   *   - Must be greater than 0.
   * - doc : Document
   *   - Legal allowance document.
   *   - Must be non-null and represent the approval/allowance document.
   * Output:
   * - boolean
   * - true when the application record is created successfully.
   * - false when validation fails, the customer is not eligible, or an approved application for the same company already exists.
   * Pre-condition:
   * - Customer instance exists.
   * - Inputs satisfy domain constraints:
   *   - company is non-null
   *   - shares > 0
   *   - amount > 0
   *   - doc is non-null
   * - Customer eligibility can be evaluated.
   * Post-condition:
   * - If successful, applications contains a new pending application linked to this customer and the given company.
   * - The new application stores the provided share count, payment amount, and allowance document.
   * - If unsuccessful, no new application is added.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    if (company == null || shares <= 0 || amount <= 0 || doc == null)
    {
      return false;
    }

    if (!isEligibleForIPO())
    {
      return false;
    }

    for (Application application : getApplications())
    {
      if (application.getStatus() == ApplicationStatus.APPROVAL
          && application.getCompany() != null
          && company.getName() != null
          && company.getName().equals(application.getCompany().getName()))
      {
        return false;
      }
    }

    Application newApplication = IpoFactory.eINSTANCE.createApplication();
    newApplication.setCompany(company);
    newApplication.setCustomer(this);
    newApplication.setShare(shares);
    newApplication.setAmountOfMoney(amount);
    newApplication.setAllowance(doc);
    newApplication.setStatus(ApplicationStatus.PENDING);
    getApplications().add(newApplication);
    return true;
    
  }

